def build_pdf(out_path):
    import pymupdf
    from PIL import Image, ImageDraw
    import io as _io

    # 一张合成的示意图（模拟资料里的插图），用于验证"抽取内嵌图 → 图形题"链路
    img = Image.new('RGB', (520, 360), 'white')
    d = ImageDraw.Draw(img)
    nodes = [(90, 80), (260, 60), (420, 110), (150, 260), (330, 280)]
    for a, b in [(0, 1), (1, 2), (0, 3), (3, 4), (4, 2), (1, 4)]:
        d.line([nodes[a], nodes[b]], fill='black', width=3)
    for i, (x, y) in enumerate(nodes):
        d.ellipse([x - 22, y - 22, x + 22, y + 22], outline='black', fill='white', width=3)
        d.text((x - 6, y - 8), 'V%d' % (i + 1), fill='black')
    d.text((20, 330), 'Figure: a weighted graph (synthetic test fixture)', fill='#333333')
    buf = _io.BytesIO()
    img.save(buf, 'PNG')
    png = buf.getvalue()

    doc = pymupdf.open()
    img_used = 0
    for ci, (title, paras) in enumerate(CHAPTERS):
        page = doc.new_page()
        y = 56
        page.insert_text((56, y), title, fontsize=17, fontname='china-s')
        y += 34
        for p in paras:
            BOX = 220                      # 给足高度，避免文字被截断（截断会让字数不可控）
            rc = page.insert_textbox(pymupdf.Rect(56, y, 540, y + BOX), p,
                                     fontsize=11, fontname='china-s', lineheight=1.5)
            if rc < 0:                     # 本页放不下 → 换页重排这一段
                page = doc.new_page()
                y = 56
                rc = page.insert_textbox(pymupdf.Rect(56, y, 540, y + BOX), p,
                                         fontsize=11, fontname='china-s', lineheight=1.5)
            y += (BOX - max(rc, 0)) + 12    # 按实际占用高度推进光标
        # 每两章插一张图（共 3 张），保证有内嵌图形可被抽取
        if ci % 2 == 0:
            if y > 480:
                page = doc.new_page()
                y = 56
            page.insert_text((56, y), '下图为本节相关示意图：', fontsize=11, fontname='china-s')
            page.insert_image(pymupdf.Rect(70, y + 14, 430, y + 262), stream=png)
            img_used += 1
    doc.save(out_path, deflate=True, garbage=3)
    doc.close()
    return img_used


