def build_golden(out_path):
    lines = ['/* 合成测试夹具：12 道自拟选择题，仅供自动化测试验证「金标集评估」流程。',
             ' * 不含任何真实试题内容；真实金标题库请放在 data/golden.js（已 gitignore）。 */',
             "'use strict';",
             'const QUESTIONS = [']
    for i, (qid, stem, opts, ans) in enumerate(GOLDEN):
        lines.append('  { id: %r, type: %r, ch: %d, kp: %r, verified: true, answer: %r,'
                     % (qid, 'mcq', 7 + i // 4, '合成夹具考点', ans))
        lines.append('    stem: %r,' % stem)
        lines.append('    options: [%s] },' % ', '.join(repr(o) for o in opts))
    lines.append('];')
    with open(out_path, 'w', encoding='utf-8', newline='\n') as f:
        f.write('\n'.join(lines) + '\n')
    return len(GOLDEN)


