    print('生成 %s（%d 道合成选择题）' % (js, n_q))

    # 自检：material_test / practice_test 要求解析后字数 >5000 且能抽到图。
    # 这里直接用 pymupdf 数一遍正文，低于阈值就报错退出——避免夹具被改小之后测试才在 CI 上红。
    import pymupdf
    doc = pymupdf.open(pdf)
    chars = sum(len(p.get_text().strip()) for p in doc)
    imgs = sum(len(p.get_images(full=True)) for p in doc)
    doc.close()
    print('自检：正文 %d 字、内嵌图 %d 张（测试要求 >5000 字、≥1 张图）' % (chars, imgs))
    if chars <= 5000 or imgs < 1:
        print('✗ 夹具不满足测试要求，请补充 CHAPTERS 内容后重新生成')
        sys.exit(1)
    print('✓ 夹具满足测试要求')
    sys.exit(0)
